const typeOptions=DNS_TYPES.map(value=>({label:value,value})); const ttlOptions=localized(() => ([{label:tr('m_7eb336e42cb5'),value:1},...[60,120,300,600,1800,3600,7200,18000,43200,86400].map(value=>({label:ttlLabel(value),value}))]))
const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return q?records.value.filter(r=>[r.type,r.name,recordContent(r)].some(v=>String(v).toLowerCase().includes(q))):records.value})
