async function loadZones(){zonesLoading.value=true;try{zones.value=(await listZones()).data;if(zones.value.length)zoneID.value=zones.value[0].id}catch(e){message.error(tr('m_b3cd1fcac7df')+err(e))}finally{zonesLoading.value=false}}
